function validate([candidates]) {
  if (!Array.isArray(candidates) || candidates.length < 1 || candidates.length > 100000) return 'candidates needs 1 to 10^5 numbers.';
  if (candidates.some(v => !Number.isInteger(v) || v < 1 || v > 10000000)) return 'Each candidate is an integer from 1 to 10^7.';
  return null;
}

