function largestCombination(candidates) {
  let best = 0;
  for (let bit = 0; bit < 24; bit++) {
    let count = 0;
    for (const value of candidates) {
      if ((value >> bit) & 1) {
        count++;
      }
    }
    best = Math.max(best, count);
  }
  return best;
}

