function largestCombination(candidates) {
  const n = candidates.length;
  let best = 0;
  for (let mask = 1; mask < (1 << n); mask++) {
    let and = -1;
    let size = 0;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) { and &= candidates[i]; size++; }
    }
    if (and > 0 && size > best) best = size;
  }
  return best;
}

