function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    const style = Math.floor(rand() * 3);
    const values = Array.from({ length: n }, () => {
      if (style === 0) return 1 + Math.floor(rand() * 10000000);
      if (style === 1) return 1 << Math.floor(rand() * 24);
      return 1 + Math.floor(rand() * 255);
    });
    return [values.map(v => Math.min(v, 10000000))];
  }
  const n = 1 + Math.floor(rand() * 10);
  const top = [3, 15, 63, 1000, 10000000][Math.floor(rand() * 5)];
  const values = Array.from({ length: n }, () => {
    if (rand() < 0.3) return 1 << Math.floor(rand() * 6);
    return 1 + Math.floor(rand() * top);
  });
  return [values];
}
